package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class DetachedVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property detached of observed source ")
  void test_detached_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> DetachedVO.tryFrom(null));
    Assertions.assertEquals(true, DetachedVO.from(true).isDetached());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> DetachedVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", DetachedVO.from(true).toString());
  }
}
